if(joinCode){localStorage.setItem('aict_group_code',joinCode.toUpperCase());setTimeout(()=>toast(`Joined class ${joinCode.toUpperCase()}`),500)}
function save(){for(const [k,v] of Object.entries({aict_name:state.name,aict_xp:state.xp,aict_correct:state.correct,aict_answered:state.answered,aict_streak:state.streak,aict_best:state.best,aict_badges:JSON.stringify(state.badges),aict_history:JSON.stringify(state.history),aict_sound:state.sound?'on':'off'}))localStorage.setItem(k,v)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function shuffle(a){const x=a.slice();for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
function level(){return Math.floor(state.xp/250)+1}
function toast(msg){const d=document.createElement('div');d.className='toast';d.textContent=msg;document.body.appendChild(d);setTimeout(()=>d.remove(),2400)}
function playSound(type){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C();const map={click:300,correct:660,wrong:170,start:420,win:784,badge:880,tick:420};const o=c.createOscillator(),g=c.createGain();o.frequency.value=map[type]||300;o.type='sine';o.connect(g);g.connect(c.destination);g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.08,c.currentTime+.02);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.12);o.start();o.stop(c.currentTime+.13)}catch(e){}}
function confetti(){const c=document.createElement('div');c.className='confetti';for(let i=0;i<45;i++){const p=document.createElement('i');p.style.left=Math.random()*100+'%';p.style.setProperty('--x',(Math.random()*260-130)+'px');p.style.animationDelay=Math.random()*.3+'s';c.appendChild(p)}document.body.appendChild(c);setTimeout(()=>c.remove(),2000)}
function award(id){if(state.badges.includes(id))return;const b=BADGES.find(x=>x[0]===id);if(!b)return;state.badges.push(id);playSound('badge');toast(`${b[3]} ${b[1]} unlocked`);save()}
function earn(xp,good){state.xp+=xp;state.answered++;if(good){state.correct++;state.streak++;state.best=Math.max(state.best,state.streak);if(state.streak>=7)award('streak')}else state.streak=0;if(state.answered===1)award('first');if(state.xp>=1000)award('master');save()}
function nav(page){state.page=page;state.libraryCategory=null;render();window.scrollTo({top:0,behavior:'smooth'});playSound('click')}

function shell(content){return `<div class="app-shell"><header class="topbar"><div class="brand"><div class="brand-mark">${ico('ai')}</div><div><strong>${APP}</strong><small>${INSTITUTION}</small></div></div><div class="top-actions"><span class="pill">Lv ${level()} · ${state.xp} XP</span><button class="icon-btn" data-action="sound" title="Sound">${ico('sound')}</button><button class="icon-btn" data-action="profile" title="Profile">${ico('profile')}</button></div></header><div class="layout"><aside class="sidebar">${navHTML()}<div class="side-card"><small>${esc(state.name)}</small><div class="xpbar"><i style="width:${Math.min(100,(state.xp%250)/2.5)}%"></i></div><small>${state.xp%250}/250 XP to next level</small></div></aside><main class="main">${content}<div class="footer">${APP} · ${AUTHOR} · ${INSTITUTION}<br><small>AI is a thinking partner, not a substitute for evidence, teacher judgement or student reflection.</small></div></main></div>${mobileNav()}</div>`}
function navHTML(){const items=[['home','home','Home'],['library','library','Task Library'],['cycle','cycle','6C Cycle'],['challenge','game','Method Challenge'],['competition','trophy','Team Competition'],['ai','ai','AI Critical Thinking Lab'],['progress','progress','My Progress'],['teacher','teacher','Teacher Dashboard']];return `<nav class="nav-group">${items.map(i=>`<button class="nav-item ${state.page===i[0]?'active':''}" data-nav="${i[0]}"><span class="nav-icon">${ico(i[1])}</span><span>${i[2]}</span></button>`).join('')}</nav>`}
function mobileNav(){return `<div class="mobile-nav">${[['home','home'],['library','library'],['cycle','cycle'],['challenge','game'],['progress','progress']].map(x=>`<button class="${state.page===x[0]?'active':''}" data-nav="${x[0]}"><span>${ico(x[1])}</span><small>${x[0]}</small></button>`).join('')}</div>`}

function home(){return shell(`<section class="hero"><span class="eyebrow">ARTIFICIAL INTELLIGENCE · CRITICAL THINKING · ENGLISH TEACHER EDUCATION</span><h1>Think first. Check twice. Teach better.</h1><p>Learn to question information, check AI suggestions, make teaching decisions and reflect on your reasoning.</p><div class="author"><div class="avatar">SS</div><div><strong>${AUTHOR}</strong><br><span class="muted">${INSTITUTION} · PhD Research Project</span></div></div><div class="home-actions"><button class="primary-btn" data-nav="cycle">🚀 Start 6C Learning</button><button class="ghost-btn" data-nav="challenge">${ico('game')} Quick Challenge</button></div></section><div class="stats"><div class="stat"><strong>${state.xp}</strong><span>Total XP</span></div><div class="stat"><strong>${state.correct}</strong><span>Correct answers</span></div><div class="stat"><strong>${state.best}</strong><span>Best streak</span></div><div class="stat"><strong>${state.badges.length}</strong><span>Badges</span></div></div><div class="section-title"><div><h2>Learning Studio</h2><p>Choose one learning route.</p></div></div><div class="grid grid-4">${[['library','library','Task Library','Short, practical classroom scenarios.'],['cycle','cycle','6C Cycle','Six clear thinking moves in one short scenario.'],['challenge','game','Method Challenge','Identify real English-teaching methods.'],['competition','trophy','Team Competition','Make quick classroom decisions.'],['ai','ai','AI Critical Thinking Lab','Ask AI for an idea without writing a special prompt.'],['progress','progress','My Progress','XP, badges and activity history.'],['teacher','teacher','Teacher Dashboard','Create a class code and launch activities.']].map(f=>`<button class="card feature-card" data-nav="${f[0]}"><div class="big-icon">${ico(f[1])}</div><h3>${f[2]}</h3><p>${f[3]}</p><span class="arrow">→</span></button>`).join('')}</div><div class="section-title"><div><h2>6C Critical Thinking Cycle</h2><p>Context → Consult → Critique → Check → Conclude → Reflect.</p></div></div><div class="cycle">${STAGES.map((s,i)=>`<div class="cycle-step"><b>${s[2]}</b><strong>${s[0]}</strong><span>${s[1]}</span></div>`).join('')}</div>`)}

function library(){const all=SCENARIOS.map((s,i)=>({i,title:s[0],scenario:s[1],cat:CATEGORIES[i%8]}));const tasks=state.libraryCategory?all.filter(x=>x.cat[0]===state.libraryCategory):all;return shell(`<div class="section-title"><div><h2>📚 Task Library</h2><p>Short, practical scenarios with simple English.</p></div><span class="pill">${SCENARIOS.length} scenarios</span></div><div class="tabs"><button class="chip ${!state.libraryCategory?'active':''}" data-cat="All">All</button>${CATEGORIES.map(c=>`<button class="chip ${state.libraryCategory===c[0]?'active':''}" data-cat="${esc(c[0])}">${esc(c[0])}</button>`).join('')}</div><div class="grid grid-3">${tasks.map(t=>`<article class="card task-card"><div class="task-icon">${ico(['cycle','ai','library','teacher','game','ai','teacher','progress'][t.i%8])}</div><span class="pill">${esc(t.cat[0])}</span><h3>${esc(t.title)}</h3><p>${esc(t.scenario)}</p><div class="task-foot"><small>3 thinking questions</small><button class="primary-btn" data-scenario="${t.i}">Open →</button></div></article>`).join('')}</div>`)}

function ensureScenario(){if(!state.scenario){const i=Math.floor(Math.random()*SCENARIOS.length);state.scenario={i,s:SCENARIOS[i],answers:[],step:0}}}
function cycle(){ensureScenario();const s=state.scenario.s;const prompts=[['1/3','Understand & Question','What is happening in this classroom, and what would you question first?'],['2/3','Consult & Check','What could AI suggest, and what would you check before using it?'],['3/3','Conclude & Reflect','What would you do as the teacher, and why? What would you change if new evidence appears?']];const p=prompts[state.scenario.step]||prompts[0];return shell(`<div class="game-shell"><div class="section-title"><div><h2>🧠 6C Critical Thinking Cycle</h2><p>Read one real classroom situation and work through six thinking moves.</p></div><span class="pill">3 short questions</span></div><div class="cycle cycle-6">${STAGES.map((x,i)=>`<div class="cycle-step ${i<=state.scenario.step?'active-step':''}"><b>${x[2]}</b><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div><div class="card scenario-card"><span class="eyebrow">REAL CLASSROOM SCENARIO</span><h2>${esc(s[0])}</h2><p class="scenario-text">${esc(s[1])}</p><div class="question-card"><div class="q-meta"><span class="pill">${p[0]}</span><span class="pill">${p[1]}</span></div><h2 class="q-title">${p[2]}</h2><textarea id="sc-answer" rows="5" placeholder="Write 1–3 clear sentences..."></textarea><div class="question-actions"><button class="primary-btn" data-action="submitScenario">${state.scenario.step===2?'Finish 6C ✓':'Continue →'}</button><button class="ghost-btn" data-action="newScenario">🔀 New scenario</button></div></div></div></div>`) }
function submitScenario(){const a=document.getElementById('sc-answer')?.value.trim();if(!a){toast('Write a short answer first.');return}state.scenario.answers.push(a);if(state.scenario.step<2){state.scenario.step++;render();return}state.xp+=80;state.answered+=3;state.correct+=3;state.streak+=3;state.best=Math.max(state.best,state.streak);award('thinker');save();const answers=state.scenario.answers.slice();state.scenario=null;confetti();playSound('win');document.getElementById('app').innerHTML=shell(`<div class="game-shell"><div class="hero"><span class="eyebrow">6C COMPLETE</span><h1>Good thinking.</h1><p>You identified the situation, questioned the idea, considered AI, checked what matters, made a decision and reflected.</p></div><div class="answer-summary">${answers.map((x,i)=>`<div class="card"><small>Question ${i+1}</small><p>${esc(x)}</p></div>`).join('')}</div><div class="home-actions"><button class="primary-btn" data-action="newScenario">🔀 Try another scenario</button><button class="ghost-btn" data-nav="progress">${ico('progress')} My Progress</button></div></div>`)}

function gameSetup(kind){const title=kind==='challenge'?'🎮 Method Challenge':'🏆 Team Competition';const subtitle=kind==='challenge'?'30 questions using real English-teaching methods.':'30 classroom-decision questions. Randomised every round.';return shell(`<div class="game-shell"><div class="section-title"><div><h2>${title}</h2><p>${subtitle}</p></div></div><div class="card setup-card"><div class="grid grid-2"><div class="field"><label>Difficulty</label><select id="g-diff"><option>Mixed</option><option>Easy</option><option>Medium</option><option>Advanced</option></select></div><div class="field"><label>Questions</label><select id="g-count"><option value="10">10</option><option value="15">15</option><option value="20">20</option><option value="25">25</option><option value="30">30</option></select></div></div>${kind==='competition'?`<div class="field"><label>Teams</label><select id="team-count"><option value="1">Solo</option><option value="2">2 teams</option><option value="3">3 teams</option><option value="4">4 teams</option></select></div><div id="team-fields" class="team-grid"></div>`:''}<button class="primary-btn" data-action="beginGame" data-kind="${kind}">🚀 Start ${kind==='challenge'?'Challenge':'Competition'}</button></div></div>`)}
function buildQuestions(kind,diff,count){let bank=kind==='challenge'?METHOD_BANK:COMP_EXTRA;if(diff!=='Mixed')bank=bank.filter(q=>q.diff===diff);return shuffle(bank).slice(0,Math.min(count,bank.length))}
function beginGame(kind){const diff=document.getElementById('g-diff')?.value||'Mixed';const count=+document.getElementById('g-count')?.value||10;const qs=buildQuestions(kind,diff,count);if(!qs.length){toast('No questions available.');return}if(kind==='challenge'){state.game={qs,index:0,score:0,answered:false,currentOpts:[]};renderGame();playSound('start')}else{const n=+(document.getElementById('team-count')?.value||1);const names=[];for(let i=0;i<n;i++)names.push(document.getElementById('team-'+i)?.value||`Team ${i+1}`);state.competition={qs,index:0,team:0,teams:names.map(name=>({name,score:0,correct:0})),answered:false,currentOpts:[],timer:null,seconds:20};renderCompetition();playSound('start')}}
function renderGame(){const g=state.game;if(!g)return;const q=g.qs[g.index];const opts=shuffle(q.options).map(text=>({text,correct:text===q.correct}));g.currentOpts=opts;document.getElementById('app').innerHTML=shell(`<div class="game-shell"><div class="game-head"><button class="ghost-btn" data-nav="challenge">← Exit</button><div class="progress-track"><i style="width:${((g.index)/g.qs.length)*100}%"></i></div><span class="pill">${g.index+1}/${g.qs.length}</span><span class="pill">${g.score} XP</span></div><div class="question-card"><div class="q-meta"><span class="pill">${esc(q.method)}</span><span class="pill">${q.diff}</span></div><h1 class="q-title">${esc(q.text)}</h1><div class="choices">${opts.map((o,i)=>`<button class="choice" data-answer="${i}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o.text)}</span></button>`).join('')}</div><div id="game-feedback"></div></div></div>`)}
function answerGame(i){const g=state.game;if(!g||g.answered)return;g.answered=true;const q=g.qs[g.index],o=g.currentOpts[i];const good=!!o?.correct;document.querySelectorAll('[data-answer]').forEach((b,idx)=>{if(g.currentOpts[idx].correct)b.classList.add('correct');if(idx===i&&!good)b.classList.add('wrong')});if(good){g.score+=25;earn(25,true);playSound('correct')}else{earn(5,false);playSound('wrong')}document.getElementById('game-feedback').innerHTML=`<div class="feedback ${good?'pop':'shake'}"><strong>${good?'✅ Correct!':'❌ Not quite.'}</strong><p>${esc(q.why)}</p><button class="primary-btn" data-action="nextGame">${g.index===g.qs.length-1?'Finish':'Next question →'}</button></div>`}
function nextGame(){const g=state.game;if(!g)return;if(g.index>=g.qs.length-1){award('method');state.history.unshift({date:new Date().toLocaleString(),type:'Method Challenge',score:g.score,questions:g.qs.length});state.history=state.history.slice(0,20);save();state.game=null;confetti();playSound('win');nav('progress');return}g.index++;g.answered=false;renderGame()}
function renderCompetition(){const c=state.competition;if(!c)return;const q=c.qs[c.index];const opts=shuffle(q.options).map(text=>({text,correct:text===q.correct}));c.currentOpts=opts;const scores=c.teams.map((t,i)=>`<div class="score ${i===c.team?'leader':''}"><span>${i===c.team?'● ':''}${esc(t.name)}</span><strong>${t.score}</strong><small>${t.correct} correct</small></div>`).join('');document.getElementById('app').innerHTML=shell(`<div class="game-shell"><div class="game-head"><button class="ghost-btn" data-nav="competition">← Exit</button><span class="pill">${c.index+1}/${c.qs.length}</span><span class="pill">${esc(c.teams[c.team].name)} turn</span><span id="comp-timer" class="timer">20</span></div><div class="scoreboard">${scores}</div><div class="question-card"><div class="q-meta"><span class="pill">${q.diff}</span><span class="pill">Classroom decision</span></div><h1 class="q-title">${esc(q.text)}</h1><div class="choices">${opts.map((o,i)=>`<button class="choice" data-comp-answer="${i}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o.text)}</span></button>`).join('')}</div><div id="comp-feedback"></div></div></div>`);startCompTimer()}
function startCompTimer(){const c=state.competition;if(!c)return;clearInterval(c.timer);c.seconds=20;const el=document.getElementById('comp-timer');c.timer=setInterval(()=>{c.seconds--;if(el)el.textContent=c.seconds; if(c.seconds<=5)playSound('tick');if(c.seconds<=0){clearInterval(c.timer);answerCompetition(-1)}},1000)}
function answerCompetition(i){const c=state.competition;if(!c||c.answered)return;c.answered=true;clearInterval(c.timer);const q=c.qs[c.index],o=i>=0?c.currentOpts[i]:null,good=!!o?.correct;if(good){c.teams[c.team].score+=100;c.teams[c.team].correct++;earn(10,true);playSound('correct')}else{earn(2,false);playSound('wrong')}document.querySelectorAll('[data-comp-answer]').forEach((b,idx)=>{if(c.currentOpts[idx].correct)b.classList.add('correct');if(idx===i&&!good)b.classList.add('wrong')});document.getElementById('comp-feedback').innerHTML=`<div class="feedback"><strong>${good?'🎯 Correct!':'⏱ Time/answer used.'}</strong><p>${esc(q.why)}</p><button class="primary-btn" data-action="nextCompetition">${c.index===c.qs.length-1?'Final scoreboard':'Next team →'}</button></div>`}
function nextCompetition(){const c=state.competition;if(!c)return;if(c.index>=c.qs.length-1){award('team');clearInterval(c.timer);state.history.unshift({date:new Date().toLocaleString(),type:'Team Competition',score:c.teams.reduce((a,t)=>a+t.score,0),questions:c.qs.length,teams:c.teams.map(t=>`${t.name}: ${t.score}`).join(' · ')});state.history=state.history.slice(0,20);save();const body=`<div class="game-shell"><div class="hero"><span class="eyebrow">COMPETITION COMPLETE</span><h1>🏆 Final scoreboard</h1><p>The game score shows activity in this round.</p></div><div class="scoreboard">${c.teams.map(t=>`<div class="score"><span>${esc(t.name)}</span><strong>${t.score}</strong><small>${t.correct} correct</small></div>`).join('')}</div><div class="home-actions"><button class="primary-btn" data-nav="competition">🔁 Play again</button><button class="ghost-btn" data-nav="progress">${ico('progress')} My Progress</button></div></div>`;state.competition=null;confetti();playSound('win');document.getElementById('app').innerHTML=shell(body);return}c.index++;c.team=(c.team+1)%c.teams.length;c.answered=false;renderCompetition()}

function progress(){return shell(`<div class="section-title"><div><h2>📈 My Progress</h2><p>Personal activity indicators from this device.</p></div><div class="home-actions"><button class="ghost-btn" data-action="profile">${ico('profile')} Edit profile</button><button class="primary-btn" data-action="exportProgress">Export</button></div></div><div class="stats"><div class="stat"><strong>${state.xp}</strong><span>XP</span></div><div class="stat"><strong>${state.correct}</strong><span>Correct</span></div><div class="stat"><strong>${state.best}</strong><span>Best streak</span></div><div class="stat"><strong>${level()}</strong><span>Level</span></div></div><div class="section-title"><div><h2>Badges</h2></div></div><div class="badge-grid">${BADGES.map(b=>`<span class="badge ${state.badges.includes(b[0])?'':'muted'}">${b[3]} ${b[1]} ${state.badges.includes(b[0])?'✓':'○'}</span>`).join('')}</div><div class="section-title"><div><h2>Recent activity</h2></div></div><div class="card">${state.history.length?`<table class="table"><thead><tr><th>Date</th><th>Activity</th><th>Score</th><th>Questions</th></tr></thead><tbody>${state.history.map(h=>`<tr><td>${esc(h.date)}</td><td>${esc(h.type)}</td><td>${esc(h.score)}</td><td>${esc(h.questions)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No activity yet. Start an activity to build your history.</div>'}</div>`)}
function exportProgress(){const data={name:state.name,xp:state.xp,correct:state.correct,best:state.best,badges:state.badges,history:state.history,exportedAt:new Date().toISOString()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='ai-ct-teacher-progress.json';a.click();URL.revokeObjectURL(a.href)}

function teacher(){const code=localStorage.getItem('aict_group_code')||'';const invite=code?`${location.origin}${location.pathname}?join=${encodeURIComponent(code)}`:'';return shell(`<div class="section-title"><div><h2>👩‍🏫 Teacher Dashboard</h2><p>Create a class code, share it, and launch activities.</p></div><span class="pill">Teacher view</span></div><div class="grid grid-3"><div class="card"><h3>Method questions</h3><strong class="big-number">${METHOD_BANK.length}</strong><p>Real English-teaching methods.</p></div><div class="card"><h3>Classroom questions</h3><strong class="big-number">${COMP_EXTRA.length}</strong><p>Short real classroom decisions.</p></div><div class="card"><h3>6C scenarios</h3><strong class="big-number">${SCENARIOS.length}</strong><p>Three thinking questions each.</p></div></div><div class="card teacher-panel"><div class="panel-head"><div><h3>🔗 Class code</h3><p class="muted">Create a code to share in your class group.</p></div><button class="primary-btn" data-action="newGroup">Create code</button></div><div class="group-code">${esc(code||'------')}</div>${invite?`<div class="invite-row"><input readonly value="${esc(invite)}" id="invite-link"><button class="ghost-btn" data-action="copyInvite">Copy link</button></div>`:''}<div class="teacher-note">The current GitHub Pages version stores activity in the browser. A shared multi-device class roster needs a secure backend/database before it can report live student progress.</div></div><div class="section-title"><div><h2>Launch in class</h2><p>Choose an activity for the lesson.</p></div></div><div class="grid grid-3"><button class="card feature-card" data-nav="challenge"><div class="big-icon">${ico('game')}</div><h3>Method Challenge</h3><p>Identify real teaching methods.</p></button><button class="card feature-card" data-nav="competition"><div class="big-icon">${ico('trophy')}</div><h3>Team Competition</h3><p>Make quick classroom decisions.</p></button><button class="card feature-card" data-nav="cycle"><div class="big-icon">${ico('cycle')}</div><h3>6C Scenario</h3><p>Question, check, decide and reflect.</p></button></div>`)}

function aiLab(){return shell(`<div class="section-title"><div><h2>🤖 AI Critical Thinking Lab</h2><p>Ask AI for an idea. Then question it, check it and make your own decision.</p></div><span class="pill">AI Assistant</span></div><div class="ai-box"><div class="grid grid-2"><div><h3>Ask AI</h3><p class="muted">Describe your classroom situation in a few words. You do not need a special prompt.</p><textarea id="ai-input" rows="8" placeholder="Example: My students are shy during speaking activities..."></textarea><div class="home-actions"><button class="primary-btn" data-action="aiCoach">🤖 Ask AI</button><button class="ghost-btn" data-action="aiExample">✨ Give me an example</button></div></div><div><h3>Think about the answer</h3><div id="ai-result" class="feedback"><span class="muted">The AI suggestion will appear here.</span></div><div class="card" style="margin-top:14px"><p><b>Question:</b> What could be wrong or missing?</p><p><b>Check:</b> What evidence would you look for?</p><p><b>Reflect:</b> What would you change?</p></div></div></div></div>`)}
async function aiCoach(){const input=document.getElementById('ai-input')?.value.trim();if(!input){toast('Describe your classroom situation first.');return}award('ai');const box=document.getElementById('ai-result');box.innerHTML='<span class="muted">🤖 Thinking…</span>';if(state.aiEndpoint){try{const r=await fetch(state.aiEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'critical-thinking-coach',prompt:`Give a short student-friendly suggestion for this future English teacher. Do not make the final decision for them. Give one useful idea, one thing to check, and one question to think about. Use simple English.\n\nSituation:\n${input}`,context:{framework:'AI-CT 6C',institution:INSTITUTION}})});if(!r.ok)throw new Error('AI');const data=await r.json().catch(()=>null);box.innerHTML=`<div class="ai-response"><strong>AI suggestion</strong><p>${esc(data?.text||data?.response||'No response text returned.')}</p></div>`;state.xp+=20;save();return}catch(e){}}
const lower=input.toLowerCase();const flags=[];if(!/because|reason|why/.test(lower))flags.push('Give one clear reason for your idea.');if(!/source|evidence|check|data|fact|study/.test(lower))flags.push('Say what information you would check.');if(!/but|however|another|different|could/.test(lower))flags.push('Think of one other possibility.');const feedback=`<strong>Coach feedback</strong><p>Your situation is clear. Now strengthen your reasoning:</p><ul>${(flags.length?flags:['Connect your idea to evidence and think about another possibility.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><b>Think about this:</b> What could make you change your decision?</p>`;box.innerHTML=`<div class="ai-response">${feedback}</div>`;state.xp+=20;save()}
function aiExample(){document.getElementById('ai-input').value='My students are shy during speaking activities. What could I try, and what should I check first?';toast('Example added. Now ask AI.');}

function profile(){const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-box"><div class="modal-head"><h2>Student profile</h2><button class="icon-btn" data-close>✕</button></div><div class="field"><label>Name</label><input id="profile-name" value="${esc(state.name)}"></div><div class="home-actions"><button class="ghost-btn" data-close>Cancel</button><button class="primary-btn" data-save-profile>Save</button></div></div>`;document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target.hasAttribute('data-close'))modal.remove();if(e.target.hasAttribute('data-save-profile')){state.name=document.getElementById('profile-name').value.trim()||'Student';save();modal.remove();render()}})}

function render(){let c='';switch(state.page){case'home':c=home();break;case'library':c=library();break;case'cycle':c=cycle();break;case'challenge':c=gameSetup('challenge');break;case'competition':c=gameSetup('competition');break;case'ai':c=aiLab();break;case'progress':c=progress();break;case'teacher':c=teacher();break;default:c=home()}document.getElementById('app').innerHTML=c}

document.addEventListener('click',e=>{
 const navEl=e.target.closest('[data-nav]');if(navEl){nav(navEl.dataset.nav);return}
 const cat=e.target.closest('[data-cat]');if(cat){state.libraryCategory=cat.dataset.cat==='All'?null:cat.dataset.cat;render();return}
 const scenario=e.target.closest('[data-scenario]');if(scenario){const i=+scenario.dataset.scenario;state.scenario={i,s:SCENARIOS[i%SCENARIOS.length],answers:[],step:0};nav('cycle');return}
 const ans=e.target.closest('[data-answer]');if(ans){answerGame(+ans.dataset.answer);return}
 const cans=e.target.closest('[data-comp-answer]');if(cans){answerCompetition(+cans.dataset.compAnswer);return}
 const action=e.target.closest('[data-action]');if(!action)return;const a=action.dataset.action;
 if(a==='sound'){state.sound=!state.sound;save();render();playSound('click')}
 else if(a==='profile')profile()
 else if(a==='newScenario'){state.scenario=null;nav('cycle')}
 else if(a==='submitScenario')submitScenario()
 else if(a==='beginGame')beginGame(action.dataset.kind)
 else if(a==='nextGame')nextGame()
 else if(a==='nextCompetition')nextCompetition()
 else if(a==='aiCoach')aiCoach()
 else if(a==='aiExample')aiExample()
 else if(a==='exportProgress')exportProgress()
 else if(a==='newGroup'){const code=Math.random().toString(36).slice(2,8).toUpperCase();localStorage.setItem('aict_group_code',code);render();toast('Class code created.');playSound('correct')}
 else if(a==='copyInvite'){const x=document.getElementById('invite-link');if(x){x.select();navigator.clipboard?.writeText(x.value).then(()=>toast('Invite link copied.'))}}
});

document.addEventListener('change',e=>{if(e.target.id==='team-count'){const n=+e.target.value;const box=document.getElementById('team-fields');if(box)box.innerHTML=n>1?Array.from({length:n},(_,i)=>`<div class="team-box"><div class="field"><label>Team ${i+1} name</label><input id="team-${i}" value="Team ${i+1}"></div></div>`).join(''):''}});

